<?php
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/ensure_courses.php';
$rows=[];try{$rows=$db->query("SELECT c.*,lc.name category_name,lc.icon category_icon,(SELECT COUNT(*) FROM learning_lessons l WHERE l.course_id=c.id AND l.enabled=1) lesson_count FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.enabled=1 ORDER BY c.featured DESC,c.id DESC")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log('Learning Hub courses list: '.$e->getMessage());}
$category=trim((string)($_GET['category']??''));
if($category!=='')$rows=array_values(array_filter($rows,fn($r)=>($r['category_name']??'')===$category));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Courses — Learning Hub</title><meta name="description" content="Practical SmartToolz Learning Hub courses for computer skills, web development, programming, AI, design, SEO and career skills."><style>body{margin:0;font-family:Inter,Arial;background:#f7f9fd;color:#172033}.wrap{width:min(1100px,calc(100% - 28px));margin:auto}.head{padding:42px 0 25px}.head a{color:#635bff;font-weight:800;font-size:13px}.head h1{font-size:40px;margin:15px 0 6px}.head p{color:#707b8e}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding-bottom:50px}.card{background:#fff;border:1px solid #e5e8ef;border-radius:18px;padding:20px;min-height:190px;display:flex;flex-direction:column}.icon{font-size:26px}.card h2{font-size:18px;margin:13px 0 7px}.card p{color:#707b8e;font-size:13px;line-height:1.6}.meta{margin-top:auto;font-size:11px;font-weight:800;color:#657086;display:flex;justify-content:space-between}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="head"><a href="/learning-hub/">← Learning Hub</a><h1>Courses</h1><p>Choose a practical learning path and start building.</p></div><div class="grid"><?php foreach($rows as $c):?><a class="card" href="/learning-hub/course.php?slug=<?=rawurlencode($c['slug'])?>"><div class="icon"><?=lh_h($c['category_icon']??'📚')?></div><h2><?=lh_h($c['title'])?></h2><p><?=lh_h($c['description']??'')?></p><div class="meta"><span><?=lh_h($c['level'])?></span><span><?=number_format((int)$c['lesson_count'])?> lessons</span></div></a><?php endforeach;if(!$rows):?><div class="card"><h2>Courses are being prepared</h2><p>The Learning Hub catalogue is initializing. Please refresh this page in a moment.</p></div><?php endif;?></div></main></body></html>
